('0b23582d-2d67-5038-83bf-d039484a8dd2'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"A group of 6 people planned to spend $10.00 each to rent a boat for an outing. At the last minute, 1 person could not go on the outing. The others then paid equally for the boat. How much did each pay?"'::jsonb,'[{"key":"A","text":"$8.00"},{"key":"B","text":"$8.33"},{"key":"C","text":"$11.67"},{"key":"D","text":"$12.00"},{"key":"E","text":"$20.00"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t5.md","source_sha256":"fb0beb8b38f3ff520bee0bf84d567ee65d0b5e7154f4a58335fa388c652dd787","source_question_id":"T5-42","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t5.md (T5-42)."'::jsonb),
('f9215d89-b696-5f84-b5ab-89e1c5584dc0'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"3x⁵ · 7x⁹ is equivalent to:"'::jsonb,'[{"key":"F","text":"10x⁴"},{"key":"G","text":"10x¹⁴"},{"key":"H","text":"10x⁴⁵"},{"key":"J","text":"21x¹⁴"},{"key":"K","text":"21x⁴⁵"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t5.md","source_sha256":"fb0beb8b38f3ff520bee0bf84d567ee65d0b5e7154f4a58335fa388c652dd787","source_question_id":"T5-43","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from book_t5.md (T5-43)."'::jsonb),
('0401e04f-ce6e-50c0-9735-db9bfd712ec9'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"A bag contains 5 yellow jellybeans, 4 red jellybeans, and 3 green jellybeans, all of the same shape and size. When 1 jellybean is randomly picked from the bag, what is the probability that it is green?"'::jsonb,'[{"key":"A","text":"1/12"},{"key":"B","text":"1/4"},{"key":"C","text":"1/3"},{"key":"D","text":"5/12"},{"key":"E","text":"2/3"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t5.md","source_sha256":"fb0beb8b38f3ff520bee0bf84d567ee65d0b5e7154f4a58335fa388c652dd787","source_question_id":"T5-44","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t5.md (T5-44)."'::jsonb),
('88c92f97-4d17-5f1f-ac08-db4c45e8edeb'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"What is the slope of the line containing the points (3, 8) and (−2, 10) in the standard (x,y) coordinate plane?"'::jsonb,'[{"key":"F","text":"1/18"},{"key":"G","text":"12/5"},{"key":"H","text":"18"},{"key":"J","text":"−5/2"},{"key":"K","text":"−2/5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t5.md","source_sha256":"fb0beb8b38f3ff520bee0bf84d567ee65d0b5e7154f4a58335fa388c652dd787","source_question_id":"T5-45","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from book_t5.md (T5-45)."'::jsonb),
