('743f84be-39e8-5cbd-aa93-58959a5fca1e'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"To become a contestant on a quiz show, a person must correctly order 4 rock stars by age, from youngest to oldest. The contestant knows which one is the oldest rock star, but randomly guesses at the order of the other 3 rock stars. What is the probability the contestant will get all 4 in the correct order?"'::jsonb,'[{"key":"F","text":"1/24"},{"key":"G","text":"1/6"},{"key":"H","text":"1/4"},{"key":"J","text":"1/3"},{"key":"K","text":"1/2"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-07","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from book_t6.md (T6-07)."'::jsonb),
