('e3a26d5d-8a1d-5c99-979d-5f9dcd5cc3a2'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"If one of the angles of a rhombus is 60° and its side length is 12 cm, then its area is ……"'::jsonb,'[{"key":"A","text":"72"},{"key":"B","text":"72√3"},{"key":"C","text":"144"},{"key":"D","text":"144√3"},{"key":"E","text":"none of the above"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-17","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t6.md (T6-17)."'::jsonb),
('f122b50c-d28e-5628-b9a7-6c59cb1bda08'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"[Figure: sinusoidal graph with maximum 3 and minimum −3, passing through the origin, completing one full period by x = π/2.]\nWhich of the following could be the equation of the above graph?"'::jsonb,'[{"key":"A","text":"y = 3 sin x"},{"key":"B","text":"y = 3 sin 2x"},{"key":"C","text":"y = sin 4x"},{"key":"D","text":"y = 3 sin 4x"},{"key":"E","text":"y = −3 sin 4x"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-18","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t6.md (T6-18)."'::jsonb),
('14883ba4-94ed-52b0-a4d9-e49d6af0e0d8'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"Students studying motion observed a cart rolling at a constant rate along a straight line. The table below gives the distance, d feet, the cart was from a reference point at 1-second intervals from t = 0 seconds to t = 5 seconds.\nt: 0, 1, 2, 3, 4, 5\nd: 15, 18, 21, 24, 27, 30\nWhich of the following equations represents this relationship between d and t ?"'::jsonb,'[{"key":"F","text":"d = t + 15"},{"key":"G","text":"d = 3t + 12"},{"key":"H","text":"d = 3t + 15"},{"key":"J","text":"d = 15t + 3"},{"key":"K","text":"d = 33t"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-19","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from book_t6.md (T6-19)."'::jsonb),
('d800814e-4120-5c48-bdfa-c67af0a4d4d6'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"What is the value of |−6| − |7 − 41| ?"'::jsonb,'[{"key":"F","text":"−40"},{"key":"G","text":"−28"},{"key":"H","text":"28"},{"key":"J","text":"40"},{"key":"K","text":"54"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-20","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from book_t6.md (T6-20)."'::jsonb),
('21a18169-e513-569d-bc61-3549128cb230'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Which of the following ordered pairs in the standard (x,y) coordinate plane satisfies the system of inequalities below?\nx > 2\ny > 0\nx + y < 5"'::jsonb,'[{"key":"A","text":"(1, 3)"},{"key":"B","text":"(2, 2)"},{"key":"C","text":"(3, 1)"},{"key":"D","text":"(3, 2)"},{"key":"E","text":"(4, 0)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-21","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t6.md (T6-21)."'::jsonb),
('1a9fb27c-26bd-5fe5-9e00-34cca5395327'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"Which of the following is equivalent to 8² · 4^0.5 ?"'::jsonb,'[{"key":"A","text":"2⁷"},{"key":"B","text":"4^4.5"},{"key":"C","text":"8^2.5"},{"key":"D","text":"16²"},{"key":"E","text":"32"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-22","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from book_t6.md (T6-22)."'::jsonb),
('5a33ec05-0da0-547e-b394-7fc561ed85d4'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"Laura plans to paint the 8-foot-high rectangular walls of her room, and before she buys paint she needs to know the area of the wall surface to be painted. Two walls are 10 feet wide, and the other 2 walls are 15 feet wide. The combined area of the 1 window and the 1 door in her room is 60 square feet. What is the area, in square feet, of the wall surface Laura plans to paint?"'::jsonb,'[{"key":"A","text":"200"},{"key":"B","text":"340"},{"key":"C","text":"360"},{"key":"D","text":"390"},{"key":"E","text":"400"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-23","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t6.md (T6-23)."'::jsonb),
('80a2f729-3ac6-57a7-8c2b-8dccb31558d7'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"A circle in the standard (x,y) coordinate plane has center C(−1, 2) and passes through A(2, 6). Line segment AB is a diameter of this circle. What are the coordinates of point B ?"'::jsonb,'[{"key":"F","text":"(−6, −2)"},{"key":"G","text":"(−5, −1)"},{"key":"H","text":"(−4, −2)"},{"key":"J","text":"(4, 2)"},{"key":"K","text":"(5, 10)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-24","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"H"'::jsonb,'"Source-keyed answer from book_t6.md (T6-24)."'::jsonb),
('4bb5c48e-acc8-5fd7-9fef-4916e8c7d386'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"In which of the following pairs are the expressions equivalent to each other?"'::jsonb,'[{"key":"A","text":"7x + 8y and 15xy"},{"key":"B","text":"y + y + y and y³"},{"key":"C","text":"4(2 + x) and 8 + x"},{"key":"D","text":"9x − x and 9"},{"key":"E","text":"−x + y and −(x − y)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-25","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"E"'::jsonb,'"Source-keyed answer from book_t6.md (T6-25)."'::jsonb),
('dbb56ded-00c2-5c4a-b103-5f5d663fd4d5'::uuid,'est','"Plane Geometry, Measurement & Transformations"'::jsonb,'medium','mcq','"If r, s, and t are three distinct lines in a plane, which of the following must be true?\nI. If r and s are parallel to t, then r is parallel to s.\nII. If r and s intersect t, then r intersects s.\nIII. If r and s are parallel and s intersects t, then r intersects t."'::jsonb,'[{"key":"A","text":"I only"},{"key":"B","text":"III only"},{"key":"C","text":"I and III only"},{"key":"D","text":"II and III only"},{"key":"E","text":"I, II, and III"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-26","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Plane Geometry, Measurement & Transformations"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t6.md (T6-26)."'::jsonb),
('195146c2-b057-586d-b6fb-d6a0969754bd'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"Which of the following equations represents the set of all points in the xy-plane each of which is a distance of 5 units from the point (5, −5) ?"'::jsonb,'[{"key":"A","text":"x² + y² = 25"},{"key":"B","text":"x² + y² − 5 = 0"},{"key":"C","text":"x² + 2xy + y² = 25"},{"key":"D","text":"(x + 5)² + (y − 5)² = 25"},{"key":"E","text":"(x − 5)² + (y + 5)² = 25"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-27","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"E"'::jsonb,'"Source-keyed answer from book_t6.md (T6-27)."'::jsonb),
('b7beabbf-ef88-5f49-8490-04c93e020109'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Julio paid 7 3/4 % sales tax on an item he bought. He figured that if he had bought the item in a neighboring state where the sales tax is 8 1/4 %, he would have paid $75 more. What was the cost of the item before tax?"'::jsonb,'[{"key":"A","text":"$15,000.00"},{"key":"B","text":"$3,750.00"},{"key":"C","text":"$1,500.00"},{"key":"D","text":"$150.00"},{"key":"E","text":"$37.50"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-28","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"A"'::jsonb,'"Source-keyed answer from book_t6.md (T6-28)."'::jsonb),
('b2142954-ef46-5d14-8b3a-517362f13e61'::uuid,'est','"Sequences, Complex Numbers & Advanced Algebra"'::jsonb,'medium','mcq','"For what positive real value of k, if any, is the determinant of the matrix [k 4; 3 k] equal to k ?\n(Note: The determinant of matrix [a b; c d] equals ad − bc.)"'::jsonb,'[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"12"},{"key":"D","text":"√12"},{"key":"E","text":"There is no such value of k."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-29","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Sequences, Complex Numbers & Advanced Algebra"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from book_t6.md (T6-29)."'::jsonb),
('3a86433f-c559-5d02-b01d-ed845aaaee28'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"Portions of the graphs represented by the functions −2x + y = 2 and x + y = 5 are shown in the standard (x,y) coordinate plane below. Although only a portion of each graph is shown, the domain of each function is all real numbers. If it can be determined, at what point do the graphs intersect?\n[Figure: two partial lines — one rising (through lower-left region toward the origin) and one falling (near (5, 0)).]"'::jsonb,'[{"key":"F","text":"(−1, 5)"},{"key":"G","text":"(1, 4)"},{"key":"H","text":"(2, 5)"},{"key":"J","text":"(4, 1)"},{"key":"K","text":"Cannot be determined from the given information"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-30","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from book_t6.md (T6-30)."'::jsonb),
('c4693291-0b62-558f-a469-e1d73b299735'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"Tammy will draft 1 player at random from a list of 20 players for her fantasy football team. Each player in the list plays only 1 position. The number of players who play a particular position is given in the table below. What is the probability that the player Tammy drafts will be a kicker or a receiver?\nPosition / Number of players: Kicker 4, Linebacker 2, Quarterback 6, Receiver 8"'::jsonb,'[{"key":"F","text":"2/25"},{"key":"G","text":"1/5"},{"key":"H","text":"2/5"},{"key":"J","text":"1/2"},{"key":"K","text":"3/5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-31","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from book_t6.md (T6-31)."'::jsonb),
('e4fe0618-7e06-5cd7-9d34-4e33ea2fb95d'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"Given u and v such that (a²)^u = a¹² and (a^v)² = a⁸ for all positive a, what is a^(u+v) ?"'::jsonb,'[{"key":"F","text":"a⁵"},{"key":"G","text":"a¹⁰"},{"key":"H","text":"a¹⁶"},{"key":"J","text":"a²⁰"},{"key":"K","text":"a²⁴"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-32","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from book_t6.md (T6-32)."'::jsonb),
('0923ef0c-9554-5aa9-a570-e82d7df0e231'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'medium','mcq','"A committee will be selected from a group of 12 women and 18 men. The committee will consist of 5 women and 5 men. Which of the following expressions gives the number of different committees that could be selected from these 30 people?"'::jsonb,'[{"key":"F","text":"₃₀P₁₀"},{"key":"G","text":"(₁₂P₅)(₁₈P₅)"},{"key":"H","text":"₃₀C₁₀"},{"key":"J","text":"(₃₀C₅)(₃₀C₅)"},{"key":"K","text":"(₁₂C₅)(₁₈C₅)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-33","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"K"'::jsonb,'"Source-keyed answer from book_t6.md (T6-33)."'::jsonb),
('a419955c-ab60-59ac-a101-d6aa1d581840'::uuid,'est','"Solid Geometry & Volume"'::jsonb,'medium','mcq','"Erika is landscaping her front yard. The yard, which is level, has the shape of a rectangle that is 60 feet wide by 80 feet long. To cover the yard with a layer of topsoil having a uniform depth of 4 inches (1/3 foot), Erika needs to use how many cubic feet of topsoil?"'::jsonb,'[{"key":"F","text":"1,600"},{"key":"G","text":"1,920"},{"key":"H","text":"4,800"},{"key":"J","text":"14,400"},{"key":"K","text":"19,200"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-34","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Solid Geometry & Volume"}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from book_t6.md (T6-34)."'::jsonb),
('670da6f8-624d-5eec-8ba3-c56163c32e48'::uuid,'est','"Statistics, Probability & Data Analysis"'::jsonb,'easy','mcq','"A tank initially contains 7 gallons of water. A faucet is opened and water begins pouring into the tank at a rate of 1.5 gallons per minute until the tank is full. Which of the following represents the volume V of water, in gallons, in the tank as a function of the time t, in minutes, that has elapsed since the faucet was opened?"'::jsonb,'[{"key":"A","text":"V(t) = 1.5 + t"},{"key":"B","text":"V(t) = 8.5 + t"},{"key":"C","text":"V(t) = 1.5t"},{"key":"D","text":"V(t) = 1.5t − 7"},{"key":"E","text":"V(t) = 1.5t + 7"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-35","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Statistics, Probability & Data Analysis"}'::jsonb,'"E"'::jsonb,'"Source-keyed answer from book_t6.md (T6-35)."'::jsonb),
('566a97c1-5985-57dc-9e2f-9a3b2d1ac6c9'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"The cost to rent a T-shirt booth at a market is $780 per year. Each T-shirt costs $8 to manufacture and is sold for $15. What is the minimum number of T-shirts that must be sold in order for the booth to operate at a profit for the year?"'::jsonb,'[{"key":"A","text":"33"},{"key":"B","text":"34"},{"key":"C","text":"52"},{"key":"D","text":"111"},{"key":"E","text":"112"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-36","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"E"'::jsonb,'"Source-keyed answer from book_t6.md (T6-36)."'::jsonb),
('ba8d917f-7796-5e44-8052-fe1bb47bcae5'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"Which of the following describes the domain of the function f, where f(x) = (x−1)(x+2) / (x+1)(x+4) ?"'::jsonb,'[{"key":"A","text":"All real numbers"},{"key":"B","text":"All real numbers except 1 and 4"},{"key":"C","text":"All real numbers except −2 and 1"},{"key":"D","text":"All real numbers except −4 and −1"},{"key":"E","text":"All real numbers except −4, −2, −1, and 1"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t6.md","source_sha256":"fff115dbcac720ded29af3b5a3d4e954934e7afdc285b7b3e484aee7cfdf97a9","source_question_id":"T6-37","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t6.md (T6-37)."'::jsonb),
